namespace axenox\Deployer\Tests\PHPUnit\Unit;

use PHPUnit\Framework\TestCase;

/**
 * Guards the package manifest and retained runtime against external recipe consumers.
 */
class LegacyDependencyRemovalTest extends TestCase
{
    // Generated by GitHub Copilot - Nov-05-2026
    /**
     * The native console must neither start nor authorize the removed recipe CLI.
     *
     * @return void
     */
    public function testConsoleUsesOnlyNativeActionCommands(): void
    {
        $page = json_decode(file_get_contents(dirname(__DIR__, 3)
            . DIRECTORY_SEPARATOR . 'Model' . DIRECTORY_SEPARATOR . '99_PAGE'
            . DIRECTORY_SEPARATOR . 'axenox.deployer.console.json'), true, 512, JSON_THROW_ON_ERROR);
        self::assertSame(['action list axenox.Deployer'], $page['contents']['start_commands']);
        self::assertSame(['/action axenox.Deployer:.*/i'], $page['contents']['allowed_commands']);
    }

    /**
     * Previously installed metadata remains readable until the normal model import.
     *
     * @return void
     */
    public function testLegacyDatatypeNamesAreStringCompatibilityOnlyAndOfferNoRecipes(): void
    {
        $workbench = new \exface\Core\CommonLogic\Workbench();
        foreach ([
            \axenox\Deployer\DataTypes\BuildRecipeDataType::class,
            \axenox\Deployer\DataTypes\DeploymentRecipeDataType::class
        ] as $class) {
            $type = new $class(new \exface\Core\CommonLogic\Selectors\DataTypeSelector($workbench, $class));
            self::assertNotInstanceOf(\exface\Core\Interfaces\DataTypes\EnumDataTypeInterface::class, $type);
            self::assertSame('CustomBuild', $type->parse('CustomBuild'));
            self::assertSame('NativePipeline', $type->parse('NativePipeline'));
        }
    }

    /**
     * The shared application's old lock/vendor contents are not edited by this package test.
     *
     * @return void
     */
    public function testPackageAndRetainedRuntimeNoLongerRequireExternalDeployer(): void
    {
        $root = dirname(__DIR__, 3);
        $manifest = json_decode(file_get_contents($root . DIRECTORY_SEPARATOR . 'composer.json'), true, 512, JSON_THROW_ON_ERROR);
        self::assertArrayNotHasKey('deployer/deployer', $manifest['require']);
        if (is_dir($root . DIRECTORY_SEPARATOR . 'Recipes')) {
            $recipes = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator(
                $root . DIRECTORY_SEPARATOR . 'Recipes', \FilesystemIterator::SKIP_DOTS
            ));
            self::assertCount(0, iterator_to_array($recipes));
        }
        foreach (['Actions', 'Common', 'DataConnectors', 'Pipelines', 'Facades', 'Factories', 'Interfaces', 'Selectors', 'Uxon'] as $directory) {
            if (! is_dir($root . DIRECTORY_SEPARATOR . $directory)) {
                continue;
            }
            $files = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator(
                $root . DIRECTORY_SEPARATOR . $directory,
                \FilesystemIterator::SKIP_DOTS
            ));
            foreach ($files as $file) {
                if ($file->getExtension() !== 'php') {
                    continue;
                }
                $source = file_get_contents($file->getPathname());
                self::assertDoesNotMatchRegularExpression('/\bnamespace\s+Deployer\s*[;{]/', $source, $file->getPathname());
                self::assertStringNotContainsString('vendor/deployer/deployer', str_replace('\\', '/', $source), $file->getPathname());
                foreach (token_get_all($source) as $token) {
                    if (is_array($token) && in_array($token[0], [T_NAME_QUALIFIED, T_NAME_FULLY_QUALIFIED], true)) {
                        self::assertFalse(str_starts_with(ltrim($token[1], '\\'), 'Deployer\\'), $file->getPathname());
                    }
                }
            }
        }
        foreach (['Build', 'Deploy'] as $action) {
            $source = file_get_contents($root . DIRECTORY_SEPARATOR . 'Actions' . DIRECTORY_SEPARATOR . $action . '.php');
            self::assertStringNotContainsString('prepareDeployerTask', $source);
            self::assertStringNotContainsString('prepareDeployerProjectFolder', $source);
        }
        foreach (new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator(
            $root . DIRECTORY_SEPARATOR . 'Model', \FilesystemIterator::SKIP_DOTS
        )) as $file) {
            if ($file->getExtension() !== 'json') {
                continue;
            }
            $source = file_get_contents($file->getPathname());
            json_decode($source, true, 512, JSON_THROW_ON_ERROR);
            self::assertStringNotContainsString('DeployerSshConnector.php', $source, $file->getPathname());
            self::assertStringNotContainsString('DataTypes/BuildRecipeDataType.php', $source, $file->getPathname());
            self::assertStringNotContainsString('DataTypes/DeploymentRecipeDataType.php', $source, $file->getPathname());
        }
    }
}
